if(PHP_SAPI!=='cli'){http_response_code(404);exit;}
$root=dirname(__DIR__);$payload=$root.'/patches/applanner-auto-v1/payload';$errors=[];$warnings=[];
$ok=static function(string $m):void{echo "[OK] {$m}\n";};$warn=static function(string $m)use(&$warnings):void{$warnings[]=$m;echo "[AVISO] {$m}\n";};$err=static function(string $m)use(&$errors):void{$errors[]=$m;echo "[ERRO] {$m}\n";};
if(version_compare(PHP_VERSION,'8.1.0','<'))$err('PHP 8.1+ é obrigatório. Atual: '.PHP_VERSION);else$ok('PHP '.PHP_VERSION);
if(!is_file($root.'/storage/installed.lock'))$err('storage/installed.lock não encontrado; execute na raiz ativa do ApPlanner.');else$ok('Instalação ativa reconhecida');
