if(!is_dir($payload))$err('Payload Auto V1 não encontrado.');
$files=[];if(is_dir($payload)){$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($payload,FilesystemIterator::SKIP_DOTS));foreach($it as $f){if(!$f->isFile())continue;$rel=str_replace('\\','/',substr($f->getPathname(),strlen($payload)+1));$files[$rel]=$f->getPathname();}ksort($files);if(count($files)<70)$err('Payload incompleto: '.count($files).' arquivos.');else$ok('Payload íntegro: '.count($files).' arquivos');}
