foreach($migrationNames as $name){$f=$payload.'/database/migrations/'.$name;if(!is_file($f)){$err('Migration ausente: '.$name);continue;}$sql=(string)file_get_contents($f);if(preg_match('/\b(DROP\s+(DATABASE|TABLE)|TRUNCATE\s+TABLE)\b/i',$sql))$err('Migration destrutiva detectada: '.$name);else$ok('Migration incremental/não destrutiva: '.$name);}
$constraints=[];$intended=[];foreach($migrationNames as $name){$sql=(string)@file_get_contents($payload.'/database/migrations/'.$name);if(preg_match_all('/CREATE\s+TABLE\s+IF\s+NOT\s+EXISTS\s+`?([A-Za-z0-9_]+)`?\s*\((.*?)\)\s*ENGINE/is',$sql,$blocks,PREG_SET_ORDER)){foreach($blocks as $b){if(preg_match_all('/\bCONSTRAINT\s+`?([A-Za-z0-9_]+)`?/i',$b[2],$cm))foreach($cm[1] as $c){$k=strtolower($c);$constraints[$k][]=$name;$intended[$k]=$b[1];}}}}
foreach($constraints as $n=>$where)if(count($where)>1)$err('Foreign key repetida no payload: '.$n.' em '.implode(', ',$where));if(!$errors)$ok('Foreign keys do payload sem colisão interna');
foreach($files as $rel=>$src){if(!str_ends_with(strtolower($rel),'.php'))continue;$out=[];$code=0;exec(escapeshellarg(PHP_BINARY).' -l '.escapeshellarg($src).' 2>&1',$out,$code);if($code!==0){$err('PHP inválido em '.$rel.': '.implode(' ',$out));break;}}if(!$errors)$ok('Lint PHP do payload aprovado');
