$pub=(string)@file_get_contents($payload.'/app/Controllers/PublicAutoController.php');if(!str_contains($pub,'GET_LOCK')||!str_contains($pub,'customer_can_reschedule')||!str_contains($pub,'NULL,:s'))$err('Reserva pública Auto não possui as proteções esperadas.');else$ok('Reserva pública Auto: sem profissional + lock + autoatendimento protegido');
