else try{
 spl_autoload_register(static function(string $class)use($root):void{$prefix='App\\';if(!str_starts_with($class,$prefix))return;$f=$root.'/app/'.str_replace('\\','/',substr($class,strlen($prefix))).'.php';if(is_file($f))require_once $f;});
 $pdo=\App\Core\Database::connection();$db=(string)$pdo->query('SELECT DATABASE()')->fetchColumn();$ok('Banco acessível: '.(string)$pdo->query('SELECT VERSION()')->fetchColumn());if($db==='')$err('Nenhum database ativo.');
 $applied=$pdo->query("SELECT migration FROM migrations WHERE migration IN ('037_applanner_arena_v1.sql','038_applanner_arena_v2_complete.sql')")->fetchAll(PDO::FETCH_COLUMN);foreach(['037_applanner_arena_v1.sql','038_applanner_arena_v2_complete.sql'] as $m)if(!in_array($m,$applied,true))$err('Pré-requisito ainda não aplicado no banco: '.$m);
 foreach(['appointments','customer_vehicles','customers','services','products','product_stock_movements','professional_commissions','financial_transactions','customer_packages','customer_memberships'] as $table){$st=$pdo->prepare('SELECT 1 FROM information_schema.TABLES WHERE TABLE_SCHEMA=? AND TABLE_NAME=?');$st->execute([$db,$table]);if(!$st->fetchColumn())$err('Tabela obrigatória ausente: '.$table);}
 if($intended){$names=array_keys($intended);$ph=implode(',',array_fill(0,count($names),'?'));$st=$pdo->prepare("SELECT CONSTRAINT_NAME,TABLE_NAME FROM information_schema.REFERENTIAL_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=? AND LOWER(CONSTRAINT_NAME) IN ($ph)");$st->execute(array_merge([$db],$names));foreach($st->fetchAll(PDO::FETCH_ASSOC) as $row){$n=strtolower((string)$row['CONSTRAINT_NAME']);$actual=(string)$row['TABLE_NAME'];$want=$intended[$n]??'';if($want!==''&&strcasecmp($actual,$want)!==0)$err("Colisão de FK: {$row['CONSTRAINT_NAME']} já pertence a {$actual}; patch espera {$want}.");}if(!$errors)$ok('Sem colisão de foreign keys com o schema atual');}
}catch(Throwable $e){$err('Falha na checagem somente-leitura do banco: '.$e->getMessage());}
if($errors){echo "\nPRE-FLIGHT AUTO V1: FALHOU (".count($errors)." erro(s)). Nenhuma alteração foi feita.\n";exit(1);}echo "\nPRE-FLIGHT AUTO V1: OK".($warnings?' com '.count($warnings).' aviso(s)':'').". Nenhuma alteração foi feita.\n";
